1	//===- MLIRGen.cpp - MLIR Generation from a Toy AST -----------------------===//
2	//
3	// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
4	// See https://llvm.org/LICENSE.txt for license information.
5	// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
6	//
7	//===----------------------------------------------------------------------===//
8	//
9	// This file implements a simple IR generation targeting MLIR from a Module AST
10	// for the Toy language.
11	//
12	//===----------------------------------------------------------------------===//
13	
14	#include "toy/MLIRGen.h"
15	#include "mlir/IR/Block.h"
16	#include "mlir/IR/Diagnostics.h"
17	#include "mlir/IR/Value.h"
18	#include "toy/AST.h"
19	#include "toy/Dialect.h"
20	
21	#include "mlir/IR/Builders.h"
22	#include "mlir/IR/BuiltinOps.h"
23	#include "mlir/IR/BuiltinTypes.h"
24	#include "mlir/IR/MLIRContext.h"
25	#include "mlir/IR/Verifier.h"
26	#include "toy/Lexer.h"
27	
28	#include "llvm/ADT/STLExtras.h"
29	#include "llvm/ADT/ScopedHashTable.h"
30	#include "llvm/ADT/SmallVector.h"
31	#include "llvm/ADT/StringRef.h"
32	#include "llvm/ADT/Twine.h"
33	#include <cassert>
34	#include <cstdint>
35	#include <functional>
36	#include <numeric>
37	#include <optional>
38	#include <vector>
39	
40	using namespace mlir::toy;
41	using namespace toy;
42	
43	using llvm::ArrayRef;
44	using llvm::cast;
45	using llvm::dyn_cast;
46	using llvm::isa;
47	using llvm::ScopedHashTableScope;
48	using llvm::SmallVector;
49	using llvm::StringRef;
50	using llvm::Twine;
51	
52	namespace {
53	
54	/// Implementation of a simple MLIR emission from the Toy AST.
55	///
56	/// This will emit operations that are specific to the Toy language, preserving
57	/// the semantics of the language and (hopefully) allow to perform accurate
58	/// analysis and transformation based on these high level semantics.
59	class MLIRGenImpl {
60	public:
61	  MLIRGenImpl(mlir::MLIRContext &context) : builder(&context) {}
62	
63	  /// Public API: convert the AST for a Toy module (source file) to an MLIR
64	  /// Module operation.
65	  mlir::ModuleOp mlirGen(ModuleAST &moduleAST) {
66	    // We create an empty MLIR module and codegen functions one at a time and
67	    // add them to the module.
68	    theModule = mlir::ModuleOp::create(builder.getUnknownLoc());
69	
70	    for (FunctionAST &f : moduleAST)
71	      mlirGen(f);
72	
73	    // Verify the module after we have finished constructing it, this will check
74	    // the structural properties of the IR and invoke any specific verifiers we
75	    // have on the Toy operations.
76	    if (failed(mlir::verify(theModule))) {
77	      theModule.emitError("module verification error");
78	      return nullptr;
79	    }
80	
81	    return theModule;
82	  }
83	
84	private:
85	  /// A "module" matches a Toy source file: containing a list of functions.
86	  mlir::ModuleOp theModule;
87	
88	  /// The builder is a helper class to create IR inside a function. The builder
89	  /// is stateful, in particular it keeps an "insertion point": this is where
90	  /// the next operations will be introduced.
91	  mlir::OpBuilder builder;
92	
93	  /// The symbol table maps a variable name to a value in the current scope.
94	  /// Entering a function creates a new scope, and the function arguments are
95	  /// added to the mapping. When the processing of a function is terminated, the
96	  /// scope is destroyed and the mappings created in this scope are dropped.
97	  llvm::ScopedHashTable<StringRef, mlir::Value> symbolTable;
98	
99	  /// Helper conversion for a Toy AST location to an MLIR location.
100	  mlir::Location loc(const Location &loc) {
101	    return mlir::FileLineColLoc::get(builder.getStringAttr(*loc.file), loc.line,
102	                                     loc.col);
103	  }
104	
105	  /// Declare a variable in the current scope, return success if the variable
106	  /// wasn't declared yet.
107	  llvm::LogicalResult declare(llvm::StringRef var, mlir::Value value) {
108	    if (symbolTable.count(var))
109	      return mlir::failure();
110	    symbolTable.insert(var, value);
111	    return mlir::success();
112	  }
113	
114	  /// Create the prototype for an MLIR function with as many arguments as the
115	  /// provided Toy AST prototype.
116	  mlir::toy::FuncOp mlirGen(PrototypeAST &proto) {
117	    auto location = loc(proto.loc());
118	
119	    // This is a generic function, the return type will be inferred later.
120	    // Arguments type are uniformly unranked tensors.
121	    llvm::SmallVector<mlir::Type, 4> argTypes(proto.getArgs().size(),
122	                                              getType(VarType{}));
123	    auto funcType = builder.getFunctionType(argTypes, {});
124	    return mlir::toy::FuncOp::create(builder, location, proto.getName(),
125	                                     funcType);
126	  }
127	
128	  /// Emit a new function and add it to the MLIR module.
129	  mlir::toy::FuncOp mlirGen(FunctionAST &funcAST) {
130	    // Create a scope in the symbol table to hold variable declarations.
131	    ScopedHashTableScope<llvm::StringRef, mlir::Value> varScope(symbolTable);
132	
133	    // Create an MLIR function for the given prototype.
134	    builder.setInsertionPointToEnd(theModule.getBody());
135	    mlir::toy::FuncOp function = mlirGen(*funcAST.getProto());
136	    if (!function)
137	      return nullptr;
138	
139	    // Let's start the body of the function now!
140	    mlir::Block &entryBlock = function.front();
141	    auto protoArgs = funcAST.getProto()->getArgs();
142	
143	    // Declare all the function arguments in the symbol table.
144	    for (const auto nameValue :
145	         llvm::zip(protoArgs, entryBlock.getArguments())) {
146	      if (failed(declare(std::get<0>(nameValue)->getName(),
147	                         std::get<1>(nameValue))))
148	        return nullptr;
149	    }
150	
151	    // Set the insertion point in the builder to the beginning of the function
152	    // body, it will be used throughout the codegen to create operations in this
153	    // function.
154	    builder.setInsertionPointToStart(&entryBlock);
155	
156	    // Emit the body of the function.
157	    if (mlir::failed(mlirGen(*funcAST.getBody()))) {
158	      function.erase();
159	      return nullptr;
160	    }
161	
162	    // Implicitly return void if no return statement was emitted.
163	    // FIXME: we may fix the parser instead to always return the last expression
164	    // (this would possibly help the REPL case later)
165	    ReturnOp returnOp;
166	    if (!entryBlock.empty())
167	      returnOp = dyn_cast<ReturnOp>(entryBlock.back());
168	    if (!returnOp) {
169	      ReturnOp::create(builder, loc(funcAST.getProto()->loc()));
170	    } else if (returnOp.hasOperand()) {
171	      // Otherwise, if this return operation has an operand then add a result to
172	      // the function.
173	      function.setType(builder.getFunctionType(
174	          function.getFunctionType().getInputs(), getType(VarType{})));
175	    }
176	
177	    return function;
178	  }
179	
180	  /// Emit a binary operation
181	  mlir::Value mlirGen(BinaryExprAST &binop) {
182	    // First emit the operations for each side of the operation before emitting
183	    // the operation itself. For example if the expression is `a + foo(a)`
184	    // 1) First it will visiting the LHS, which will return a reference to the
185	    //    value holding `a`. This value should have been emitted at declaration
186	    //    time and registered in the symbol table, so nothing would be
187	    //    codegen'd. If the value is not in the symbol table, an error has been
188	    //    emitted and nullptr is returned.
189	    // 2) Then the RHS is visited (recursively) and a call to `foo` is emitted
190	    //    and the result value is returned. If an error occurs we get a nullptr
191	    //    and propagate.
192	    //
193	    mlir::Value lhs = mlirGen(*binop.getLHS());
194	    if (!lhs)
195	      return nullptr;
196	    mlir::Value rhs = mlirGen(*binop.getRHS());
197	    if (!rhs)
198	      return nullptr;
199	    auto location = loc(binop.loc());
200	
201	    // Derive the operation name from the binary operator. At the moment we only
202	    // support '+' and '*'.
203	    switch (binop.getOp()) {
204	    case '+':
205	      return AddOp::create(builder, location, lhs, rhs);
206	    case '*':
207	      return MulOp::create(builder, location, lhs, rhs);
208	    }
209	
210	    emitError(location, "invalid binary operator '") << binop.getOp() << "'";
211	    return nullptr;
212	  }
213	
214	  /// This is a reference to a variable in an expression. The variable is
215	  /// expected to have been declared and so should have a value in the symbol
216	  /// table, otherwise emit an error and return nullptr.
217	  mlir::Value mlirGen(VariableExprAST &expr) {
218	    if (auto variable = symbolTable.lookup(expr.getName()))
219	      return variable;
220	
221	    emitError(loc(expr.loc()), "error: unknown variable '")
222	        << expr.getName() << "'";
223	    return nullptr;
224	  }
225	
226	  /// Emit a return operation. This will return failure if any generation fails.
227	  llvm::LogicalResult mlirGen(ReturnExprAST &ret) {
228	    auto location = loc(ret.loc());
229	
230	    // 'return' takes an optional expression, handle that case here.
231	    mlir::Value expr = nullptr;
232	    if (ret.getExpr().has_value()) {
233	      if (!(expr = mlirGen(**ret.getExpr())))
234	        return mlir::failure();
235	    }
236	
237	    // Otherwise, this return operation has zero operands.
238	    ReturnOp::create(builder, location,
239	                     expr ? ArrayRef(expr) : ArrayRef<mlir::Value>());
240	    return mlir::success();
241	  }
242	
243	  /// Emit a literal/constant array. It will be emitted as a flattened array of
244	  /// data in an Attribute attached to a `toy.constant` operation.
245	  /// See documentation on [Attributes](LangRef.md#attributes) for more details.
246	  /// Here is an excerpt:
247	  ///
248	  ///   Attributes are the mechanism for specifying constant data in MLIR in
249	  ///   places where a variable is never allowed [...]. They consist of a name
250	  ///   and a concrete attribute value. The set of expected attributes, their
251	  ///   structure, and their interpretation are all contextually dependent on
252	  ///   what they are attached to.
253	  ///
254	  /// Example, the source level statement:
255	  ///   var a<2, 3> = [[1, 2, 3], [4, 5, 6]];
256	  /// will be converted to:
257	  ///   %0 = "toy.constant"() {value: dense<tensor<2x3xf64>,
258	  ///     [[1.000000e+00, 2.000000e+00, 3.000000e+00],
259	  ///      [4.000000e+00, 5.000000e+00, 6.000000e+00]]>} : () -> tensor<2x3xf64>
260	  ///
261	  mlir::Value mlirGen(LiteralExprAST &lit) {
262	    auto type = getType(lit.getDims());
263	
264	    // The attribute is a vector with a floating point value per element
265	    // (number) in the array, see `collectData()` below for more details.
266	    std::vector<double> data;
267	    data.reserve(llvm::product_of(lit.getDims()));
268	    collectData(lit, data);
269	
270	    // The type of this attribute is tensor of 64-bit floating-point with the
271	    // shape of the literal.
272	    mlir::Type elementType = builder.getF64Type();
273	    auto dataType = mlir::RankedTensorType::get(lit.getDims(), elementType);
274	
275	    // This is the actual attribute that holds the list of values for this
276	    // tensor literal.
277	    auto dataAttribute =
278	        mlir::DenseElementsAttr::get(dataType, llvm::ArrayRef(data));
279	
280	    // Build the MLIR op `toy.constant`. This invokes the `ConstantOp::build`
281	    // method.
282	    return ConstantOp::create(builder, loc(lit.loc()), type, dataAttribute);
283	  }
284	
285	  /// Recursive helper function to accumulate the data that compose an array
286	  /// literal. It flattens the nested structure in the supplied vector. For
287	  /// example with this array:
288	  ///  [[1, 2], [3, 4]]
289	  /// we will generate:
290	  ///  [ 1, 2, 3, 4 ]
291	  /// Individual numbers are represented as doubles.
292	  /// Attributes are the way MLIR attaches constant to operations.
293	  void collectData(ExprAST &expr, std::vector<double> &data) {
294	    if (auto *lit = dyn_cast<LiteralExprAST>(&expr)) {
295	      for (auto &value : lit->getValues())
296	        collectData(*value, data);
297	      return;
298	    }
299	
300	    assert(isa<NumberExprAST>(expr) && "expected literal or number expr");
301	    data.push_back(cast<NumberExprAST>(expr).getValue());
302	  }
303	
304	  /// Emit a call expression. It emits specific operations for the `transpose`
305	  /// builtin. Other identifiers are assumed to be user-defined functions.
306	  mlir::Value mlirGen(CallExprAST &call) {
307	    llvm::StringRef callee = call.getCallee();
308	    auto location = loc(call.loc());
309	
310	    // Codegen the operands first.
311	    SmallVector<mlir::Value, 4> operands;
312	    for (auto &expr : call.getArgs()) {
313	      auto arg = mlirGen(*expr);
314	      if (!arg)
315	        return nullptr;
316	      operands.push_back(arg);
317	    }
318	
319	    // Builtin calls have their custom operation, meaning this is a
320	    // straightforward emission.
321	    if (callee == "transpose") {
322	      if (call.getArgs().size() != 1) {
323	        emitError(location, "MLIR codegen encountered an error: toy.transpose "
324	                            "does not accept multiple arguments");
325	        return nullptr;
326	      }
327	      return TransposeOp::create(builder, location, operands[0]);
328	    }
329	
330	    // Otherwise this is a call to a user-defined function. Calls to
331	    // user-defined functions are mapped to a custom call that takes the callee
332	    // name as an attribute.
333	    return GenericCallOp::create(builder, location, callee, operands);
334	  }
335	
336	  /// Emit a print expression. It emits specific operations for two builtins:
337	  /// transpose(x) and print(x).
338	  llvm::LogicalResult mlirGen(PrintExprAST &call) {
339	    auto arg = mlirGen(*call.getArg());
340	    if (!arg)
341	      return mlir::failure();
342	
343	    PrintOp::create(builder, loc(call.loc()), arg);
344	    return mlir::success();
345	  }
346	
347	  /// Emit a constant for a single number (FIXME: semantic? broadcast?)
348	  mlir::Value mlirGen(NumberExprAST &num) {
349	    return ConstantOp::create(builder, loc(num.loc()), num.getValue());
350	  }
351	
352	  /// Dispatch codegen for the right expression subclass using RTTI.
353	  mlir::Value mlirGen(ExprAST &expr) {
354	    switch (expr.getKind()) {
355	    case toy::ExprAST::Expr_BinOp:
356	      return mlirGen(cast<BinaryExprAST>(expr));
357	    case toy::ExprAST::Expr_Var:
358	      return mlirGen(cast<VariableExprAST>(expr));
359	    case toy::ExprAST::Expr_Literal:
360	      return mlirGen(cast<LiteralExprAST>(expr));
361	    case toy::ExprAST::Expr_Call:
362	      return mlirGen(cast<CallExprAST>(expr));
363	    case toy::ExprAST::Expr_Num:
364	      return mlirGen(cast<NumberExprAST>(expr));
365	    default:
366	      emitError(loc(expr.loc()))
367	          << "MLIR codegen encountered an unhandled expr kind '"
368	          << Twine(expr.getKind()) << "'";
369	      return nullptr;
370	    }
371	  }
372	
373	  /// Handle a variable declaration, we'll codegen the expression that forms the
374	  /// initializer and record the value in the symbol table before returning it.
375	  /// Future expressions will be able to reference this variable through symbol
376	  /// table lookup.
377	  mlir::Value mlirGen(VarDeclExprAST &vardecl) {
378	    auto *init = vardecl.getInitVal();
379	    if (!init) {
380	      emitError(loc(vardecl.loc()),
381	                "missing initializer in variable declaration");
382	      return nullptr;
383	    }
384	
385	    mlir::Value value = mlirGen(*init);
386	    if (!value)
387	      return nullptr;
388	
389	    // We have the initializer value, but in case the variable was declared
390	    // with specific shape, we emit a "reshape" operation. It will get
391	    // optimized out later as needed.
392	    if (!vardecl.getType().shape.empty()) {
393	      value = ReshapeOp::create(builder, loc(vardecl.loc()),
394	                                getType(vardecl.getType()), value);
395	    }
396	
397	    // Register the value in the symbol table.
398	    if (failed(declare(vardecl.getName(), value)))
399	      return nullptr;
400	    return value;
401	  }
402	
403	  /// Codegen a list of expression, return failure if one of them hit an error.
404	  llvm::LogicalResult mlirGen(ExprASTList &blockAST) {
405	    ScopedHashTableScope<StringRef, mlir::Value> varScope(symbolTable);
406	    for (auto &expr : blockAST) {
407	      // Specific handling for variable declarations, return statement, and
408	      // print. These can only appear in block list and not in nested
409	      // expressions.
410	      if (auto *vardecl = dyn_cast<VarDeclExprAST>(expr.get())) {
411	        if (!mlirGen(*vardecl))
412	          return mlir::failure();
413	        continue;
414	      }
415	      if (auto *ret = dyn_cast<ReturnExprAST>(expr.get()))
416	        return mlirGen(*ret);
417	      if (auto *print = dyn_cast<PrintExprAST>(expr.get())) {
418	        if (mlir::failed(mlirGen(*print)))
419	          return mlir::success();
420	        continue;
421	      }
422	
423	      // Generic expression dispatch codegen.
424	      if (!mlirGen(*expr))
425	        return mlir::failure();
426	    }
427	    return mlir::success();
428	  }
429	
430	  /// Build a tensor type from a list of shape dimensions.
431	  mlir::Type getType(ArrayRef<int64_t> shape) {
432	    // If the shape is empty, then this type is unranked.
433	    if (shape.empty())
434	      return mlir::UnrankedTensorType::get(builder.getF64Type());
435	
436	    // Otherwise, we use the given shape.
437	    return mlir::RankedTensorType::get(shape, builder.getF64Type());
438	  }
439	
440	  /// Build an MLIR type from a Toy AST variable type (forward to the generic
441	  /// getType above).
442	  mlir::Type getType(const VarType &type) { return getType(type.shape); }
443	};
444	
445	} // namespace
446	
447	namespace toy {
448	
449	// The public API for codegen.
450	mlir::OwningOpRef<mlir::ModuleOp> mlirGen(mlir::MLIRContext &context,
451	                                          ModuleAST &moduleAST) {
452	  return MLIRGenImpl(context).mlirGen(moduleAST);
453	}
454	
455	} // namespace toy
