57	//===----------------------------------------------------------------------===//
58	// ToyToLLVM Conversion Patterns
59	//===----------------------------------------------------------------------===//
60	
61	namespace {
62	/// Lowers `toy.print` to a loop nest calling `printf` on each of the individual
63	/// elements of the array.
64	class PrintOpLowering : public OpConversionPattern<toy::PrintOp> {
65	public:
66	  using OpConversionPattern<toy::PrintOp>::OpConversionPattern;
67	
68	  LogicalResult
69	  matchAndRewrite(toy::PrintOp op, OpAdaptor adaptor,
70	                  ConversionPatternRewriter &rewriter) const override {
71	    auto *context = rewriter.getContext();
72	    auto memRefType = llvm::cast<MemRefType>((*op->operand_type_begin()));
73	    auto memRefShape = memRefType.getShape();
74	    auto loc = op->getLoc();
75	
76	    ModuleOp parentModule = op->getParentOfType<ModuleOp>();
77	
78	    // Get a symbol reference to the printf function, inserting it if necessary.
79	    auto printfRef = getOrInsertPrintf(rewriter, parentModule);
80	    Value formatSpecifierCst = getOrCreateGlobalString(
81	        loc, rewriter, "frmt_spec", StringRef("%f \0", 4), parentModule);
82	    Value newLineCst = getOrCreateGlobalString(
83	        loc, rewriter, "nl", StringRef("\n\0", 2), parentModule);
84	
85	    // Create a loop for each of the dimensions within the shape.
86	    SmallVector<Value, 4> loopIvs;
87	    for (unsigned i = 0, e = memRefShape.size(); i != e; ++i) {
88	      auto lowerBound = arith::ConstantIndexOp::create(rewriter, loc, 0);
89	      auto upperBound =
90	          arith::ConstantIndexOp::create(rewriter, loc, memRefShape[i]);
91	      auto step = arith::ConstantIndexOp::create(rewriter, loc, 1);
92	      auto loop =
93	          scf::ForOp::create(rewriter, loc, lowerBound, upperBound, step);
94	      for (Operation &nested : make_early_inc_range(*loop.getBody()))
95	        rewriter.eraseOp(&nested);
96	      loopIvs.push_back(loop.getInductionVar());
97	
98	      // Terminate the loop body.
99	      rewriter.setInsertionPointToEnd(loop.getBody());
100	
101	      // Insert a newline after each of the inner dimensions of the shape.
102	      if (i != e - 1)
103	        LLVM::CallOp::create(rewriter, loc, getPrintfType(context), printfRef,
104	                             newLineCst);
105	      scf::YieldOp::create(rewriter, loc);
106	      rewriter.setInsertionPointToStart(loop.getBody());
107	    }
108	
109	    // Generate a call to printf for the current element of the loop.
110	    auto elementLoad =
111	        memref::LoadOp::create(rewriter, loc, op.getInput(), loopIvs);
112	    LLVM::CallOp::create(rewriter, loc, getPrintfType(context), printfRef,
113	                         ArrayRef<Value>({formatSpecifierCst, elementLoad}));
114	
115	    // Notify the rewriter that this operation has been removed.
116	    rewriter.eraseOp(op);
117	    return success();
118	  }
119	
120	private:
121	  /// Create a function declaration for printf, the signature is:
122	  ///   * `i32 (i8*, ...)`
123	  static LLVM::LLVMFunctionType getPrintfType(MLIRContext *context) {
124	    auto llvmI32Ty = IntegerType::get(context, 32);
125	    auto llvmPtrTy = LLVM::LLVMPointerType::get(context);
126	    auto llvmFnType = LLVM::LLVMFunctionType::get(llvmI32Ty, llvmPtrTy,
127	                                                  /*isVarArg=*/true);
128	    return llvmFnType;
129	  }
130	
131	  /// Return a symbol reference to the printf function, inserting it into the
132	  /// module if necessary.
133	  static FlatSymbolRefAttr getOrInsertPrintf(PatternRewriter &rewriter,
134	                                             ModuleOp module) {
135	    auto *context = module.getContext();
136	    if (module.lookupSymbol<LLVM::LLVMFuncOp>("printf"))
137	      return SymbolRefAttr::get(context, "printf");
138	
139	    // Insert the printf function into the body of the parent module.
140	    PatternRewriter::InsertionGuard insertGuard(rewriter);
141	    rewriter.setInsertionPointToStart(module.getBody());
142	    LLVM::LLVMFuncOp::create(rewriter, module.getLoc(), "printf",
143	                             getPrintfType(context));
144	    return SymbolRefAttr::get(context, "printf");
145	  }
146	
147	  /// Return a value representing an access into a global string with the given
148	  /// name, creating the string if necessary.
149	  static Value getOrCreateGlobalString(Location loc, OpBuilder &builder,
150	                                       StringRef name, StringRef value,
151	                                       ModuleOp module) {
152	    // Create the global at the entry of the module.
153	    LLVM::GlobalOp global;
154	    if (!(global = module.lookupSymbol<LLVM::GlobalOp>(name))) {
155	      OpBuilder::InsertionGuard insertGuard(builder);
156	      builder.setInsertionPointToStart(module.getBody());
157	      auto type = LLVM::LLVMArrayType::get(
158	          IntegerType::get(builder.getContext(), 8), value.size());
159	      global = LLVM::GlobalOp::create(builder, loc, type, /*isConstant=*/true,
160	                                      LLVM::Linkage::Internal, name,
161	                                      builder.getStringAttr(value),
162	                                      /*alignment=*/0);
163	    }
164	
165	    // Get the pointer to the first character in the global string.
166	    Value globalPtr = LLVM::AddressOfOp::create(builder, loc, global);
167	    Value cst0 = LLVM::ConstantOp::create(builder, loc, builder.getI64Type(),
168	                                          builder.getIndexAttr(0));
169	    return LLVM::GEPOp::create(
170	        builder, loc, LLVM::LLVMPointerType::get(builder.getContext()),
171	        global.getType(), globalPtr, ArrayRef<Value>({cst0, cst0}));
172	  }
173	};
174	} // namespace
