98	/// Returns a Toy AST resulting from parsing the file or a nullptr on error.
99	static std::unique_ptr<toy::ModuleAST>
100	parseInputFile(llvm::StringRef filename) {
101	  llvm::ErrorOr<std::unique_ptr<llvm::MemoryBuffer>> fileOrErr =
102	      llvm::MemoryBuffer::getFileOrSTDIN(filename);
103	  if (std::error_code ec = fileOrErr.getError()) {
104	    llvm::errs() << "Could not open input file: " << ec.message() << "\n";
105	    return nullptr;
106	  }
107	  auto buffer = fileOrErr.get()->getBuffer();
108	  LexerBuffer lexer(buffer.begin(), buffer.end(), std::string(filename));
109	  Parser parser(lexer);
110	  return parser.parseModule();
111	}
