113	static int loadMLIR(mlir::MLIRContext &context,
114	                    mlir::OwningOpRef<mlir::ModuleOp> &module) {
115	  // Handle '.toy' input to the compiler.
116	  if (inputType != InputType::MLIR &&
117	      !llvm::StringRef(inputFilename).ends_with(".mlir")) {
118	    auto moduleAST = parseInputFile(inputFilename);
119	    if (!moduleAST)
120	      return 6;
121	    module = mlirGen(context, *moduleAST);
122	    return !module ? 1 : 0;
123	  }
124	
125	  // Otherwise, the input is '.mlir'.
126	  llvm::ErrorOr<std::unique_ptr<llvm::MemoryBuffer>> fileOrErr =
127	      llvm::MemoryBuffer::getFileOrSTDIN(inputFilename);
128	  if (std::error_code ec = fileOrErr.getError()) {
129	    llvm::errs() << "Could not open input file: " << ec.message() << "\n";
130	    return -1;
131	  }
132	
133	  // Parse the input mlir.
134	  llvm::SourceMgr sourceMgr;
135	  sourceMgr.AddNewSourceBuffer(std::move(*fileOrErr), llvm::SMLoc());
136	  module = mlir::parseSourceFile<mlir::ModuleOp>(sourceMgr, &context);
137	  if (!module) {
138	    llvm::errs() << "Error can't load file " << inputFilename << "\n";
139	    return 3;
140	  }
141	  return 0;
142	}
