144	static int loadAndProcessMLIR(mlir::MLIRContext &context,
145	                              mlir::OwningOpRef<mlir::ModuleOp> &module) {
146	  if (int error = loadMLIR(context, module))
147	    return error;
148	
149	  mlir::PassManager pm(module.get()->getName());
150	  // Apply any generic pass manager command line options and run the pipeline.
151	  if (mlir::failed(mlir::applyPassManagerCLOptions(pm)))
152	    return 4;
153	
154	  // Check to see what granularity of MLIR we are compiling to.
155	  bool isLoweringToAffine = emitAction >= Action::DumpMLIRAffine;
156	  bool isLoweringToLLVM = emitAction >= Action::DumpMLIRLLVM;
157	
158	  if (enableOpt || isLoweringToAffine) {
159	    // Inline all functions into main and then delete them.
160	    pm.addPass(mlir::createInlinerPass());
161	
162	    // Now that there is only one function, we can infer the shapes of each of
163	    // the operations.
164	    mlir::OpPassManager &optPM = pm.nest<mlir::toy::FuncOp>();
165	    optPM.addPass(mlir::toy::createShapeInferencePass());
166	    optPM.addPass(mlir::createCanonicalizerPass());
167	    optPM.addPass(mlir::createCSEPass());
168	  }
169	
170	  if (isLoweringToAffine) {
171	    // Partially lower the toy dialect.
172	    pm.addPass(mlir::toy::createLowerToAffinePass());
173	
174	    // Add a few cleanups post lowering.
175	    mlir::OpPassManager &optPM = pm.nest<mlir::func::FuncOp>();
176	    optPM.addPass(mlir::createCanonicalizerPass());
177	    optPM.addPass(mlir::createCSEPass());
178	
179	    // Add optimizations if enabled.
180	    if (enableOpt) {
181	      optPM.addPass(mlir::affine::createLoopFusionPass());
182	      optPM.addPass(mlir::affine::createAffineScalarReplacementPass());
183	    }
184	  }
185	
186	  if (isLoweringToLLVM) {
187	    // Finish lowering the toy IR to the LLVM dialect.
188	    pm.addPass(mlir::toy::createLowerToLLVMPass());
189	    // This is necessary to have line tables emitted and basic
190	    // debugger working. In the future we will add proper debug information
191	    // emission directly from our frontend.
192	    pm.addPass(mlir::LLVM::createDIScopeForLLVMFuncOpPass());
193	  }
194	
195	  if (mlir::failed(pm.run(*module)))
196	    return 4;
197	  return 0;
198	}
