200	static int dumpAST() {
201	  if (inputType == InputType::MLIR) {
202	    llvm::errs() << "Can't dump a Toy AST when the input is MLIR\n";
203	    return 5;
204	  }
205	
206	  auto moduleAST = parseInputFile(inputFilename);
207	  if (!moduleAST)
208	    return 1;
209	
210	  dump(*moduleAST);
211	  return 0;
212	}
