303	  mlir::DialectRegistry registry;
304	  mlir::func::registerAllExtensions(registry);
305	  mlir::LLVM::registerInlinerInterface(registry);
306	
307	  mlir::MLIRContext context(registry);
308	  // Load our Dialect in this MLIR Context.
309	  context.getOrLoadDialect<mlir::toy::ToyDialect>();
310	
